package com.smartattendance.service;

import com.smartattendance.dto.*;import com.smartattendance.exception.ResourceNotFoundException;import com.smartattendance.model.*;import com.smartattendance.repository.StudentRepository;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;
@Service
public class StudentService{private final StudentRepository repo;private final UserService users;public StudentService(StudentRepository repo,UserService users){this.repo=repo;this.users=users;}public Page<StudentResponse> search(String q,Pageable p){return(q==null||q.isBlank()?repo.findAll(p):repo.findByNameContainingIgnoreCaseOrRollNumberContainingIgnoreCaseOrDepartmentContainingIgnoreCase(q,q,q,p)).map(this::toResponse);}public StudentResponse get(Long id){return toResponse(find(id));}public StudentResponse create(StudentRequest r){Student s=new Student();apply(s,r);return toResponse(repo.save(s));}public StudentResponse update(Long id,StudentRequest r){Student s=find(id);apply(s,r);return toResponse(repo.save(s));}public void delete(Long id){repo.delete(find(id));}public Student find(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Student",id));}private void apply(Student s,StudentRequest r){s.setRollNumber(r.rollNumber());s.setName(r.name());s.setEmail(r.email());s.setDepartment(r.department());s.setSemester(r.semester());s.setUser(r.userId()==null?null:users.find(r.userId()));}public StudentResponse toResponse(Student s){return new StudentResponse(s.getId(),s.getRollNumber(),s.getName(),s.getEmail(),s.getDepartment(),s.getSemester(),s.getUser()==null?null:s.getUser().getId());}}
